// settings
const int ROWS = 12,
          COLUMNS = 20;

const vec4 BACKGROUND = vec4(80, 57, 76 , 255) / 255.,
           SQUARECOLOR = vec4(255, 239, 150,  255) / 255.;

// constants
const float DIAGONALTOSIDE = 1.4142;

struct square 
{
    vec2 centre;
    float sideLength;
    float radians;
    vec4 color;
};

float getAngle(vec2 origin, vec2 dir)
{
    dir = dir - origin;
    return atan(dir.x, dir.y);
}

bool isInSquare(square checkSq, vec2 coords)
{
    float sqSin = sin(checkSq.radians);
    float sqCos = cos(checkSq.radians);
    mat2 rotationMatrix = mat2(sqCos,-sqSin,sqSin,sqCos);

    coords = (coords - checkSq.centre) * rotationMatrix;
    coords = checkSq.centre + coords;
    coords = abs( coords - checkSq.centre );

    return max( coords.x, coords.y ) < checkSq.sideLength / 2.;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = BACKGROUND;

    vec2 COUNT = vec2(COLUMNS, ROWS),
         BetweenSq = iResolution.xy / ( COUNT + 1. ),
         diag = BetweenSq * DIAGONALTOSIDE / 2.;

    float squareSide = min(diag.x, diag.y) * 0.9;

    vec2 Pos = floor( fragCoord / BetweenSq +.5 ) -.5;
    if ( Pos.x>0. && Pos.y>0. && Pos.x < COUNT.x && Pos.y < COUNT.y )
    {
        Pos = Pos*BetweenSq + BetweenSq/2.;
        square sq = square(Pos, squareSide, getAngle(Pos, iMouse.xy), SQUARECOLOR);
        if (isInSquare(sq, fragCoord)) fragColor = sq.color;
    }

}
